// The single file in this package that reaches into Riverpod's internals.
//
// `package:riverpod/riverpod.dart` does not export the `$ClassProvider` base
// class, yet every notifier provider — hand written, family or generated by
// `riverpod_generator` — extends it. Matching on the public `NotifierProvider`
// classes alone would miss all code-generated providers, so this import is not
// avoidable. Keeping it in one file keeps the blast radius to a single place if
// Riverpod ever reshapes those types.
//
// ignore_for_file: implementation_imports, invalid_use_of_internal_member

import 'package:riverpod/riverpod.dart';
import 'package:riverpod/src/internals.dart' show $ClassProvider;

/// The signature of [ProviderContainer]'s retry policy.
///
/// Declared here rather than imported: Riverpod's own `Retry` typedef is not
/// exported publicly, and Dart function types are structural, so this one is
/// interchangeable with it.
typedef Retry = Duration? Function(int retryCount, Object error);

/// A [Retry] policy that never retries.
///
/// Useful when asserting on the error state of an async provider: Riverpod's
/// default policy retries on any non-`Error` exception, which would emit extra
/// states while the test waits.
Duration? noRetry(int retryCount, Object error) => null;

/// Any notifier provider — `NotifierProvider`, `AsyncNotifierProvider`,
/// `StreamNotifierProvider`, their families and their generated counterparts.
typedef NotifierProviderOf<NotifierT extends AnyNotifier<Object?, Object?>> =
    $ClassProvider<NotifierT, Object?, Object?, Object?>;

/// Reads the notifier exposed by [provider].
NotifierT readNotifier<NotifierT extends AnyNotifier<Object?, Object?>>(
  ProviderContainer container,
  NotifierProviderOf<NotifierT> provider,
) {
  return container.read(provider.notifier);
}
